True def transform(grid):
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row}
    bg = max(colors, key=lambda v: sum(row.count(v) for row in grid))
    out = [row[:] for row in grid]

    # Fill background rectangles enclosed by the colored outline. In the demos,
    # a broad rectangle may also be completed by the bottom edge of the grid.
    for top in range(h):
        for bottom in range(top + 2, h + 1):
            for left in range(w):
                for right in range(left + 2, w):
                    if bottom == h and right - left - 1 < 2:
                        continue
                    if any(grid[top][c] == bg for c in range(left, right + 1)):
                        continue
                    if bottom < h and any(grid[bottom][c] == bg for c in range(left, right + 1)):
                        continue
                    if any(grid[r][left] == bg or grid[r][right] == bg
                           for r in range(top + 1, bottom)):
                        continue
                    if any(grid[r][c] != bg
                           for r in range(top + 1, bottom)
                           for c in range(left + 1, right)):
                        continue
                    for r in range(top + 1, bottom):
                        for c in range(left + 1, right):
                            out[r][c] = 4
    return out
